'use strict';
// Only unsaved editor state is stored, for this tab and signed-in account.
window.TradeDeskDrafts=(()=>{
 const prefix='td_trade_draft_v1:';
 const account=()=>typeof userEmail==='string'?userEmail.trim().toLowerCase():'';
 const key=id=>account()?prefix+encodeURIComponent(account())+':'+String(id||'new'):null;
 function save(id,value){const name=key(id);if(!name)return false;try{const text=JSON.stringify({...value,version:1});if(text.length>350000)return false;sessionStorage.setItem(name,text);return true;}catch{return false;}}
 function load(id){const name=key(id);if(!name)return null;try{const text=sessionStorage.getItem(name);if(!text||text.length>350000)return null;const value=JSON.parse(text);if(value.version!==1||!value.fields||typeof value.fields!=='object'||Array.isArray(value.fields))return null;return value;}catch{return null;}}
 function clear(id){try{const name=key(id);if(name)sessionStorage.removeItem(name);}catch{}}
 function clearAll(){try{Object.keys(sessionStorage).filter(name=>name.startsWith(prefix)).forEach(name=>sessionStorage.removeItem(name));}catch{}}
 return {save,load,clear,clearAll};
})();
